-- ---------------------------------------------------------------------------
-- STEP 9: Review — existing products not matched to any Integrate short_name
-- ---------------------------------------------------------------------------

SELECT id, name, short_name, is_active
FROM   ironmongery_products
WHERE  short_name IS NULL
ORDER  BY name;

